/**
 * syno_mermaid — 给 Synology Note Station 的 TinyMCE 4 加 Mermaid 图表渲染
 *
 * 设计要点
 * --------
 * 1) 为什么存 <img> 而不是内联 <svg>
 *    TinyMCE 4 的 schema 是 HTML5 元素集合，不含 svg/g/path/text 等 SVG 元素，
 *    editor.getContent() 序列化时会把整个 <svg> 剥掉（笔记一保存图就没了）。
 *    img 在 notestation.js 的 valid_elements 白名单里（src/width/height/style/class 均允许），
 *    因此把渲染结果转成 data:image/svg+xml;base64 存进 img，既能保存又能在
 *    DSM 网页版 / 手机 App / 导出 HTML 里原样显示（三端一致）。
 * 2) 源码存在 img 的 data-mermaid 属性里（encodeURIComponent 编码）。
 *    valid_elements 的 img 规则默认不含 data-*，安装脚本会给它补上 |data-mermaid。
 * 3) 渲染库 mermaid.min.js 随插件目录一起打进 asar，完全离线，不依赖 CDN。
 */
tinymce.PluginManager.add('syno_mermaid', function (editor, url) {
    var PLUGIN_URL = (typeof url === 'string' && url) ? url : (tinymce.baseURL + '/plugins/syno_mermaid');
    var LIB_URL = PLUGIN_URL + '/mermaid.min.js';

    var lib = window.mermaid || null;
    var loading = false;
    var waiters = [];
    var seq = 0;

    var MAX_W = 700;          // 编辑器正文宽度约 700，超出按比例缩
    var DEFAULT_CODE = 'graph TD\n  A[开始] --> B{判断}\n  B -->|是| C[执行]\n  B -->|否| D[结束]';

    var MONO = 'SFMono-Regular, Menlo, Consolas, "Courier New", monospace';

    /* ------------------------------------------------------------------ */
    /* 库加载                                                              */
    /* ------------------------------------------------------------------ */

    /** 一次性初始化 mermaid（主题、字体、标签渲染方式） */
    function initLib() {
        if (!window.mermaid) { return; }
        lib = window.mermaid;
        try {
            lib.initialize({
                startOnLoad: false,
                theme: 'default',
                // loose：允许 htmlLabels（中文换行/居中更自然）；内容来自用户自己的笔记
                securityLevel: 'loose',
                fontFamily: '-apple-system, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", Arial, sans-serif',
                flowchart: { htmlLabels: true, useMaxWidth: false, curve: 'basis' },
                sequence: { useMaxWidth: false },
                gantt: { useMaxWidth: false },
                themeVariables: { fontSize: '14px' }
            });
        } catch (e) { /* 重复 initialize 会抛错，忽略 */ }
    }

    function flushWaiters(err) {
        var list = waiters.slice();
        waiters.length = 0;
        for (var i = 0; i < list.length; i++) {
            try { list[i](err, lib); } catch (e) { /* ignore */ }
        }
    }

    /**
     * 解析成绝对 URL（页面是 file://，相对路径必须靠 location 解析）
     * @param {string} u 原始地址
     * @returns {string} 绝对地址
     */
    function absUrl(u) {
        try { return new URL(u, location.href).href; } catch (e) { return String(u); }
    }

    /**
     * 列出所有可能的库地址，按可靠性排序。
     * TinyMCE 4 的 ScriptLoader 只有 loadScripts / add，没有 loadScript（那是 TinyMCE 3），
     * 所以这里自己建 <script> 标签，并对路径做多路兜底。
     * @returns {string[]} 候选地址
     */
    function libCandidates() {
        var out = [];
        function push(dir) {
            if (!dir) { return; }
            var u = absUrl(String(dir).replace(/\/+$/, '') + '/mermaid.min.js');
            if (out.indexOf(u) < 0) { out.push(u); }
        }
        push(url);                                   // TinyMCE 传入的插件目录
        try {                                        // 从已加载的 plugin.min.js 反推
            var ss = document.getElementsByTagName('script');
            for (var i = 0; i < ss.length; i++) {
                var m = (ss[i].src || '').match(/^(.*\/plugins\/syno_mermaid)\/plugin(?:\.min)?\.js(?:[?#].*)?$/);
                if (m) { push(m[1]); }
            }
        } catch (e) { /* ignore */ }
        if (tinymce.baseURL) { push(tinymce.baseURL + '/plugins/syno_mermaid'); }
        push('plugins/syno_mermaid');                             // 相对当前页
        push('webman/modules/TinyMCE/js/tinymce/plugins/syno_mermaid');
        return out;
    }

    /**
     * 加载单个脚本（20s 超时，失败时移除节点以免污染 DOM）
     * @param {string} src 绝对地址
     * @param {function(Error|null)} cb 回调
     */
    function loadScriptOnce(src, cb) {
        var s = document.createElement('script');
        var done = false;
        function fin(err) {
            if (done) { return; }
            done = true;
            s.onload = s.onerror = null;
            if (err && s.parentNode) {
                try { s.parentNode.removeChild(s); } catch (e) { /* ignore */ }
            }
            cb(err);
        }
        s.type = 'text/javascript';
        s.async = true;
        s.src = src;
        s.onload = function () { fin(null); };
        s.onerror = function () { fin(new Error('找不到 ' + src)); };
        var host = document.head || document.getElementsByTagName('head')[0] || document.body;
        host.appendChild(s);
        window.setTimeout(function () { fin(new Error('超时 ' + src)); }, 20000);
    }

    /** 依次尝试候选地址，成功（window.mermaid 就绪）即回调 */
    function loadLib(cb) {
        var urls = libCandidates();
        var i = 0;
        function next() {
            if (window.mermaid) { cb(null); return; }
            if (i >= urls.length) {
                cb(new Error('无法加载 mermaid 库（已尝试 ' + urls.length + ' 个路径）'));
                return;
            }
            loadScriptOnce(urls[i++], function () { next(); });
        }
        next();
    }

    /** 保证库已就绪；同一时刻只发一次 script 请求 */
    function ensureLib(cb) {
        if (lib || window.mermaid) {
            initLib();
            cb(null, lib);
            return;
        }
        waiters.push(cb);
        if (loading) { return; }
        loading = true;
        loadLib(function (err) {
            loading = false;
            if (err || !window.mermaid) {
                flushWaiters(err || new Error('mermaid 库未就绪'));
                return;
            }
            initLib();
            flushWaiters(null);
        });
    }

    /* ------------------------------------------------------------------ */
    /* 渲染                                                                */
    /* ------------------------------------------------------------------ */

    /** 清掉 mermaid 渲染时在 <body> 留下的临时节点 */
    function cleanup(id) {
        var nodes = [document.getElementById(id), document.getElementById('d' + id)];
        for (var i = 0; i < nodes.length; i++) {
            var n = nodes[i];
            if (n && n.parentNode) { n.parentNode.removeChild(n); }
        }
    }

    /**
     * 渲染期间临时拦截「数组转字符串」的几条路径（修 Note Station 页面里的 Prototype 污染）。
     *
     * 背景：Note Station 桌面端加载了 Prototype.js，它给 Array.prototype 挂了 each 方法；
     *      mermaid 的图表解析器会把「样式数组」里的元素直接当样式用，一旦数组里混进了
     *      函数对象（Prototype 的 each），拼出来的就是一段几十 KB 的函数源码，被塞进 SVG 的
     *      style="..." 属性。属性里含引号和 < 号 → SVG 不是合法 XML → 浏览器拒绝渲染，
     *      笔记里就变成一张裂图（只剩 alt 文字）。
     *
     *      同一个污染会走两条不同的路径：
     *        - Array.prototype.join     —— 样式数组 join 成 CSS
     *        - Array.prototype.reduce   —— 样式数组 reduce 拼成 CSS
     *      两条都要堵，否则换一张图又会裂。
     *
     * 修法：渲染期间把数组里的非字符串（函数）元素替换成空串，保证拼出来的永远是合法 CSS。
     *      渲染结束立刻还原，不影响应用其它代码。
     *
     * @returns {function} 还原函数（务必在渲染结束后调用）
     */
    function guardArrayStringify() {
        var origJoin = Array.prototype.join;
        var origReduce = Array.prototype.reduce;
        var origReduceRight = Array.prototype.reduceRight;

        function hasFn(arr) {
            for (var i = 0; i < arr.length; i++) {
                if (typeof arr[i] === 'function') { return true; }
            }
            return false;
        }
        function clean(arr) {
            var copy = new Array(arr.length);
            for (var i = 0; i < arr.length; i++) {
                copy[i] = (typeof arr[i] === 'function') ? '' : arr[i];
            }
            return copy;
        }

        Array.prototype.join = function (sep) {
            if (!hasFn(this)) { return origJoin.apply(this, arguments); }
            return origJoin.call(clean(this), sep);
        };
        Array.prototype.reduce = function (fn, init) {
            if (!hasFn(this)) { return origReduce.apply(this, arguments); }
            return origReduce.call(clean(this), fn, init);
        };
        Array.prototype.reduceRight = function (fn, init) {
            if (!hasFn(this)) { return origReduceRight.apply(this, arguments); }
            return origReduceRight.call(clean(this), fn, init);
        };

        return function () {
            Array.prototype.join = origJoin;
            Array.prototype.reduce = origReduce;
            Array.prototype.reduceRight = origReduceRight;
        };
    }

    /**
     * 校验 SVG 是否为合法 XML —— 存成 data URI 图片时，非法 XML 会直接变成裂图。
     * @param {string} svg SVG 源码
     * @returns {boolean} 是否合法
     */
    function isWellFormed(svg) {
        try {
            var doc = new DOMParser().parseFromString(svg, 'image/svg+xml');
            return !doc.querySelector('parsererror');
        } catch (e) {
            return false;
        }
    }

    /**
     * 兜底修复：属性值里出现裸的 < > & 会让 XML 非法（浏览器直接拒绝渲染，笔记里就是裂图）。
     * 只在检测到 XML 非法时才动手，正常路径完全不改写。
     * @param {string} svg SVG 源码
     * @returns {string} 修复后的 SVG
     */
    function repairSvg(svg) {
        try {
            return svg.replace(/="([^"]*)"/g, function (m, v) {
                var bareAmp = /&(?!(#\d+|#x[0-9a-fA-F]+|[a-zA-Z][a-zA-Z0-9]*);)/.test(v);
                if (v.indexOf('<') < 0 && v.indexOf('>') < 0 && !bareAmp) { return m; }
                var s = v
                    .replace(/&(?!(#\d+|#x[0-9a-fA-F]+|[a-zA-Z][a-zA-Z0-9]*);)/g, '&amp;')
                    .replace(/</g, '&lt;')
                    .replace(/>/g, '&gt;');
                return '="' + s + '"';
            });
        } catch (e) {
            return svg;
        }
    }

    /**
     * 把 mermaid 源码渲染成 SVG 字符串。
     * @param {string} code 图定义
     * @param {function(Error, string)} cb 回调
     */
    function render(code, cb) {
        ensureLib(function (err) {
            if (err) { cb(err); return; }
            var id = 'synoMermaidG' + (++seq) + 'x' + Date.now().toString(36);
            var restore = guardArrayStringify();
            var p;
            try {
                p = lib.render(id, String(code));
            } catch (e) {
                restore();
                cleanup(id);
                cb(e);
                return;
            }
            if (!p || typeof p.then !== 'function') {
                restore();
                cleanup(id);
                cb(new Error('渲染接口不可用'));
                return;
            }
            p.then(function (res) {
                restore();
                cleanup(id);
                var svg = (typeof res === 'string') ? res : (res && res.svg);
                if (!svg || svg.indexOf('<svg') < 0) {
                    cb(new Error('渲染结果为空'));
                    return;
                }
                if (!isWellFormed(svg)) {
                    // 兜底：属性值里混进了 < > &（多半是页面里的库把 JS 源码塞进了 style 属性）
                    var fixed = repairSvg(svg);
                    if (fixed !== svg && isWellFormed(fixed)) {
                        cb(null, fixed);
                        return;
                    }
                    cb(new Error('渲染结果不是合法 SVG（可能被页面里的其它库干扰），请重试'));
                    return;
                }
                cb(null, svg);
            })['catch'](function (e) {
                restore();
                cleanup(id);
                cb(e || new Error('渲染失败'));
            });
        });
    }

    /** 从 SVG 的 viewBox / width 推断自然尺寸 */
    function svgSize(svg) {
        var vb = /viewBox\s*=\s*["']([^"']+)["']/.exec(svg);
        if (vb) {
            var n = vb[1].trim().split(/[\s,]+/);
            var w = parseFloat(n[2]);
            var h = parseFloat(n[3]);
            if (w > 0 && h > 0) { return { w: w, h: h }; }
        }
        var mw = /<svg[^>]*\swidth\s*=\s*["']([\d.]+)/.exec(svg);
        var mh = /<svg[^>]*\sheight\s*=\s*["']([\d.]+)/.exec(svg);
        if (mw && mh) {
            return { w: parseFloat(mw[1]), h: parseFloat(mh[1]) };
        }
        return { w: 600, h: 300 };
    }

    /** SVG 字符串 -> data URI（base64，按 UTF-8 编码，中文安全） */
    function svgToDataUri(svg) {
        var b64;
        try {
            if (window.TextEncoder) {
                var bytes = new window.TextEncoder().encode(svg);
                var bin = '';
                for (var i = 0; i < bytes.length; i += 8192) {
                    bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 8192));
                }
                b64 = window.btoa(bin);
            } else {
                b64 = window.btoa(unescape(encodeURIComponent(svg)));
            }
        } catch (e) {
            b64 = window.btoa(unescape(encodeURIComponent(svg)));
        }
        return 'data:image/svg+xml;base64,' + b64;
    }

    /** 组装最终写进笔记的 <img> */
    function buildImg(svg, code) {
        var s = svgSize(svg);
        var w = Math.round(s.w);
        var h = Math.round(s.h);
        if (w > MAX_W) {
            h = Math.round(h * MAX_W / w);
            w = MAX_W;
        }
        w = Math.max(120, w);
        h = Math.max(60, h);
        return '<img class="syno-mermaid" src="' + svgToDataUri(svg) + '"'
            + ' width="' + w + '" height="' + h + '" alt="Mermaid 图表"'
            + ' data-mermaid="' + encodeURIComponent(code) + '"'
            + ' style="max-width:100%;height:auto;border:0;display:block;margin:14px auto;" />';
    }

    /* ------------------------------------------------------------------ */
    /* 写入编辑器                                                          */
    /* ------------------------------------------------------------------ */

    /** 插入新图，或就地替换已有的图 */
    function applyImg(html, replaceEl) {
        editor.undoManager.transact(function () {
            if (replaceEl && replaceEl.parentNode) {
                var doc = editor.getDoc();
                var wrap = doc.createElement('div');
                wrap.innerHTML = html;
                var node = wrap.firstChild;
                if (node) { replaceEl.parentNode.replaceChild(node, replaceEl); }
            } else {
                // 末尾补一个空段落，避免插入后光标无处可去
                editor.insertContent(html + '<p><br></p>');
            }
        });
        editor.nodeChanged();
    }

    /** 当前光标 / 选区是否落在一张 mermaid 图上 */
    function currentImg() {
        var node = null;
        try {
            node = editor.selection.getNode();
        } catch (e) { /* ignore */ }
        while (node) {
            if (node.nodeName === 'IMG' && editor.dom.hasClass(node, 'syno-mermaid')) {
                return node;
            }
            node = node.parentNode;
        }
        return null;
    }

    function decodeCode(img) {
        var raw = img.getAttribute('data-mermaid') || '';
        if (!raw) { return ''; }
        try { return decodeURIComponent(raw); } catch (e) { return raw; }
    }

    /**
     * 自动修复「裂图」：老版本插入的图，其 data URI 里的 SVG 非法，浏览器加载失败。
     * 这里探测每张图的 src，探测失败就用 data-mermaid 里的源码重新渲染并原地替换。
     */
    function repairImages() {
        var body = null;
        try { body = editor.getBody && editor.getBody(); } catch (e) { /* ignore */ }
        if (!body || !body.querySelectorAll) { return; }
        var imgs = body.querySelectorAll('img.syno-mermaid');
        for (var i = 0; i < imgs.length; i++) {
            (function (img) {
                var src = img.getAttribute('src') || '';
                if (!src || img.getAttribute('data-nsh-fixed')) { return; }
                var probe = new Image();
                probe.onerror = function () {
                    var code = decodeCode(img);
                    if (!code) { return; }
                    render(code, function (err, svg) {
                        if (err || !svg) { return; }
                        var doc = editor.getDoc();
                        var tmp = doc.createElement('div');
                        tmp.innerHTML = buildImg(svg, code);
                        var node = tmp.firstChild;
                        if (node) {
                            node.setAttribute('data-nsh-fixed', '1');
                            if (img.parentNode) { img.parentNode.replaceChild(node, img); }
                        }
                    });
                };
                probe.src = src;
            })(imgs[i]);
        }
    }

    /* ------------------------------------------------------------------ */
    /* 放大预览（大图缩到正文宽度后文字只有几像素，需要能看原尺寸）          */
    /* ------------------------------------------------------------------ */

    /**
     * 全屏遮罩里以 100% 原始尺寸展示图，可拖动滚动条查看细节。
     * @param {string} svg SVG 源码
     */
    function openZoom(svg) {
        if (!svg) { return; }
        var old = document.getElementById('syno-mermaid-zoom');
        if (old && old.parentNode) { old.parentNode.removeChild(old); }

        var size = svgSize(svg);
        var wrap = document.createElement('div');
        wrap.id = 'syno-mermaid-zoom';
        wrap.style.cssText = 'position:fixed;left:0;top:0;right:0;bottom:0;z-index:2147483000;'
            + 'background:rgba(24,32,42,.62);display:flex;align-items:center;justify-content:center;';

        var box = document.createElement('div');
        box.style.cssText = 'background:#fff;border-radius:12px;box-shadow:0 20px 60px rgba(0,0,0,.4);'
            + 'max-width:94vw;max-height:92vh;display:flex;flex-direction:column;overflow:hidden;';

        var bar = document.createElement('div');
        bar.style.cssText = 'display:flex;align-items:center;padding:9px 14px;border-bottom:1px solid #e6ecf3;'
            + 'font:13px/1.4 -apple-system,"PingFang SC",sans-serif;color:#5a6672;flex:0 0 auto;';

        var title = document.createElement('span');
        title.style.cssText = 'flex:1;';
        title.textContent = 'Mermaid 图表 · ' + Math.round(size.w) + ' × ' + Math.round(size.h) + '（100%）';

        var close = document.createElement('button');
        close.type = 'button';
        close.textContent = '关闭';
        close.style.cssText = 'border:1px solid #d6dee8;background:#f7f9fc;border-radius:6px;'
            + 'padding:3px 12px;cursor:pointer;font-size:12.5px;color:#2f3b4a;';

        var scroll = document.createElement('div');
        scroll.style.cssText = 'overflow:auto;padding:16px;background:#fff;';

        var img = document.createElement('img');
        img.src = svgToDataUri(svg);
        img.alt = 'Mermaid 图表';
        img.style.cssText = 'display:block;max-width:none;height:auto;width:' + Math.round(size.w) + 'px;';

        scroll.appendChild(img);
        bar.appendChild(title);
        bar.appendChild(close);
        box.appendChild(bar);
        box.appendChild(scroll);
        wrap.appendChild(box);
        document.body.appendChild(wrap);

        function shut(e) {
            if (e && e.keyCode && e.keyCode !== 27) { return; }
            document.removeEventListener('keydown', shut, true);
            if (wrap.parentNode) { wrap.parentNode.removeChild(wrap); }
        }
        close.addEventListener('click', function () { shut(); });
        wrap.addEventListener('click', function (e) { if (e.target === wrap) { shut(); } });
        document.addEventListener('keydown', shut, true);
    }

    /* ------------------------------------------------------------------ */
    /* 编辑对话框                                                          */
    /* ------------------------------------------------------------------ */

    function toast(msg, isErr) {
        try {
            var id = 'syno-mermaid-toast';
            var old = document.getElementById(id);
            if (old && old.parentNode) { old.parentNode.removeChild(old); }
            var el = document.createElement('div');
            el.id = id;
            el.textContent = msg;
            el.style.cssText = 'position:fixed;left:50%;bottom:36px;transform:translateX(-50%);'
                + 'background:' + (isErr ? '#b3395b' : 'rgba(47,59,74,.94)') + ';color:#fff;'
                + 'font:13px/1.6 -apple-system,"PingFang SC",sans-serif;padding:8px 16px;'
                + 'border-radius:16px;z-index:999999;box-shadow:0 4px 14px rgba(0,0,0,.18);'
                + 'pointer-events:none;transition:opacity .3s;';
            document.body.appendChild(el);
            window.setTimeout(function () {
                el.style.opacity = '0';
                window.setTimeout(function () {
                    if (el.parentNode) { el.parentNode.removeChild(el); }
                }, 320);
            }, isErr ? 3200 : 1800);
        } catch (e) { /* ignore */ }
    }

    function openDialog(existing) {
        var code = existing ? decodeCode(existing) : DEFAULT_CODE;
        var previewToken = 0;
        var win = null;
        var lastSvg = '';

        function renderPreview(host) {
            var my = ++previewToken;
            host.innerHTML = '<div style="color:#98a0a9;font:13px sans-serif;padding:18px 0;">渲染中…</div>';
            render(host.__code || '', function (err, svg) {
                if (my !== previewToken) { return; }
                if (err) {
                    host.innerHTML = '<div style="color:#b3395b;font:13px/1.7 sans-serif;padding:14px;text-align:left;white-space:pre-wrap;">'
                        + escapeHtml(String(err.message || err)) + '</div>';
                    return;
                }
                // 预览按容器宽度自适应：mermaid 输出的 svg 带固定 width/内联 style，
                // 用 !important 的样式规则覆盖，避免拼接 style 属性造成重复属性。
                host.innerHTML = '<style>.syno-mermaid-fit svg{max-width:100%!important;height:auto!important;'
                    + 'display:block;margin:0 auto}</style>'
                    + '<div class="syno-mermaid-fit" style="overflow:auto;max-width:100%;">' + svg + '</div>';
                lastSvg = svg;
            });
        }

        win = editor.windowManager.open({
            title: existing ? 'Mermaid 图表 · 编辑' : 'Mermaid 图表 · 新建',
            width: 780,
            height: 600,
            body: [
                {
                    type: 'textbox',
                    name: 'code',
                    multiline: true,
                    rows: 12,
                    value: code,
                    classes: 'syno-mermaid-code',
                    style: 'width:100%;box-sizing:border-box;font-family:' + MONO + ';font-size:12.5px;'
                        + 'line-height:1.6;border:1px solid #dbe3ec;border-radius:6px;padding:8px 10px;resize:vertical;'
                },
                {
                    type: 'container',
                    name: 'prev',
                    html: '<div class="syno-mermaid-prev" style="margin-top:10px;padding:12px;border:1px solid #e2e8f0;'
                        + 'border-radius:8px;background:#fbfcfe;max-height:250px;overflow:auto;text-align:center;">'
                        + '<div style="color:#98a0a9;font:13px sans-serif;padding:18px 0;">预览区</div></div>'
                }
            ],
            buttons: [
                {
                    text: '放大预览',
                    onclick: function () {
                        if (!lastSvg) {
                            toast('还没有可预览的图，检查左侧源码是否有语法错误', true);
                            return;
                        }
                        openZoom(lastSvg);
                    }
                },
                { text: '取消', onclick: function () { win.close(); } },
                {
                    text: existing ? '更新' : '插入',
                    subtype: 'primary',
                    onclick: submit
                }
            ],
            onsubmit: function (e) {
                e.preventDefault();
                submit();
            }
        });

        // 绑定输入 -> 实时预览（TinyMCE 的控件 DOM 可能晚一拍才就绪，延时 + 兜底取值）
        var ta = null;
        var host = null;

        function bind() {
            try {
                var el = win.getEl();
                if (!el) { return false; }
                ta = el.querySelector('textarea.syno-mermaid-code') || el.querySelector('textarea');
                host = el.querySelector('.syno-mermaid-prev');
                return !!(ta && host);
            } catch (e) {
                return false;
            }
        }

        var timer = null;
        function schedule() {
            if (!host || !ta) { return; }
            host.__code = ta.value;
            if (timer) { window.clearTimeout(timer); }
            timer = window.setTimeout(function () { renderPreview(host); }, 320);
        }

        /** 取当前源码：textarea 绑定失败时回落到控件 API / 初始值，保证「插入」始终可用 */
        function currentCode() {
            if (ta && typeof ta.value === 'string') { return ta.value; }
            try {
                var arr = win.find('textarea');
                if (arr && arr[0] && typeof arr[0].value === 'function') { return arr[0].value(); }
            } catch (e) { /* ignore */ }
            return code;
        }

        window.setTimeout(function () {
            if (!bind()) {
                window.setTimeout(function () { bind(); }, 160);
            }
            if (ta && host) {
                ta.addEventListener('input', schedule);
                ta.addEventListener('keyup', schedule);
                host.__code = ta.value;
                schedule();
                try { ta.focus(); } catch (e) { /* ignore */ }
            }
        }, 50);

        function submit() {
            var cur = currentCode();
            if (!String(cur).trim()) {
                toast('Mermaid 源码不能为空', true);
                return;
            }
            render(cur, function (err, svg) {
                if (err) {
                    toast('渲染失败：' + (err.message || err), true);
                    return;
                }
                applyImg(buildImg(svg, cur), existing);
                try { win.close(); } catch (e) { /* ignore */ }
                toast(existing ? '图表已更新（⌘Z 可撤销）' : '图表已插入（⌘Z 可撤销）');
            });
        }
    }

    function escapeHtml(s) {
        return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    }

    /* ------------------------------------------------------------------ */
    /* 把 ```mermaid 代码块批量转成图                                       */
    /* ------------------------------------------------------------------ */

    var MERMAID_HEAD = /^\s*(graph\s+(TD|TB|BT|LR|RL)|flowchart\s+(TD|TB|BT|LR|RL)|sequenceDiagram|classDiagram|classDiagramV2|stateDiagram(-v2)?|erDiagram|journey|gantt|pie|quadrantChart|requirementDiagram|gitGraph|mindmap|timeline|sankey-beta|xychart-beta|block-beta|packet-beta|architecture-beta|C4Context|C4Container)\b/i;

    function looksLikeMermaid(text) {
        return MERMAID_HEAD.test(String(text || '').slice(0, 400));
    }

    /** 判断一个 <pre> 是不是 mermaid 代码块（语言标记优先，其次看内容特征） */
    function isMermaidBlock(pre) {
        var lang = (pre.getAttribute('data-md-lang') || pre.getAttribute('data-nsh-lang') || '').toLowerCase();
        if (lang === 'mermaid') { return true; }
        var codeEl = pre.querySelector('code');
        if (codeEl) {
            var cls = codeEl.className || '';
            if (/\blanguage-mermaid\b/.test(cls) || /\bmd-mermaid\b/.test(cls)) { return true; }
        }
        return looksLikeMermaid(pre.textContent || '');
    }

    /**
     * 扫描全文，把 mermaid 代码块渲染成图。
     * 串行渲染：mermaid 内部依赖全局 id，并发容易互相干扰。
     * @param {function} done 全部完成后的回调（可选）
     */
    function renderBlocks(done) {
        var body = null;
        try { body = editor.getBody(); } catch (e) { return; }
        if (!body) { return; }

        var pres = body.querySelectorAll('pre');
        var jobs = [];
        for (var i = 0; i < pres.length; i++) {
            var pre = pres[i];
            if (pre.getAttribute('data-nsh-mermaid') === '1') { continue; }
            if (!isMermaidBlock(pre)) { continue; }
            var code = pre.textContent || '';
            if (!String(code).trim()) { continue; }
            jobs.push({ pre: pre, code: code });
        }
        if (!jobs.length) {
            if (typeof done === 'function') { done(0); }
            return;
        }

        var results = [];
        var idx = 0;

        function step() {
            if (idx >= jobs.length) { commit(); return; }
            var job = jobs[idx++];
            render(job.code, function (err, svg) {
                if (!err) {
                    results.push({ pre: job.pre, html: buildImg(svg, job.code) });
                }
                step();
            });
        }

        function commit() {
            if (!results.length) {
                if (typeof done === 'function') { done(0); }
                return;
            }
            editor.undoManager.transact(function () {
                var doc = editor.getDoc();
                for (var k = 0; k < results.length; k++) {
                    var r = results[k];
                    if (!r.pre || !r.pre.parentNode) { continue; }
                    var wrap = doc.createElement('div');
                    wrap.innerHTML = r.html;
                    var node = wrap.firstChild;
                    if (node) { r.pre.parentNode.replaceChild(node, r.pre); }
                }
            });
            editor.nodeChanged();
            toast('已渲染 ' + results.length + ' 个 Mermaid 图表');
            if (typeof done === 'function') { done(results.length); }
        }

        step();
    }

    // 供 syno_markdown（粘贴后）与 syno_beautify（一键美化）调用
    window.__synoRenderMermaid = function () { renderBlocks(); };

    /* ------------------------------------------------------------------ */
    /* 工具栏按钮 + 双击编辑                                                */
    /* ------------------------------------------------------------------ */

    // 图标：两个节点框 + 折线箭头（深色 #2f3b4a，与美化按钮一致）
    var ICON_URI = 'data:image/svg+xml;base64,'
        + 'PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHZpZXdCb3g9IjAgMCAyMCAyMCI+'
        + 'PGcgZmlsbD0ibm9uZSIgc3Ryb2tlPSIjMmYzYjRhIiBzdHJva2Utd2lkdGg9IjEuMiIgc3Ryb2tlLWxp'
        + 'bmVqb2luPSJyb3VuZCIgc3Ryb2tlLWxpbmVjYXA9InJvdW5kIj48cmVjdCB4PSIyLjQiIHk9IjIuOCIg'
        + 'd2lkdGg9IjYuNCIgaGVpZ2h0PSI0LjQiIHJ4PSIxLjEiLz48cmVjdCB4PSIxMS4yIiB5PSIxMi42IiB3'
        + 'aWR0aD0iNi40IiBoZWlnaHQ9IjQuNCIgcng9IjEuMSIvPjxwYXRoIGQ9Ik01LjYgNy4ydjQuNmExLjIg'
        + 'MS4yIDAgMCAwIDEuMiAxLjJoMy4yIi8+PHBhdGggZD0iTTkuMiAxMS41bDEuNCAxLjUtMS40IDEuNSIv'
        + 'PjwvZz48L3N2Zz4=';

    function applyIcon(btn) {
        try {
            var el = btn && btn.getEl && btn.getEl();
            if (!el) { return; }
            var ico = el.querySelector('.mce-ico');
            if (!ico) {
                ico = document.createElement('i');
                ico.className = 'mce-ico';
                var first = el.firstChild;
                if (first) { el.insertBefore(ico, first); } else { el.appendChild(ico); }
            }
            ico.style.backgroundImage = 'url("' + ICON_URI + '")';
            ico.style.backgroundRepeat = 'no-repeat';
            ico.style.backgroundPosition = 'center center';
            ico.style.backgroundSize = '20px 20px';
            ico.style.width = '20px';
            ico.style.height = '20px';
            ico.style.display = 'inline-block';
        } catch (e) { /* ignore */ }
    }

    editor.addButton('syno_mermaid', {
        icon: 'none',
        image: ICON_URI,
        tooltip: 'Mermaid 图表：插入新图 / 编辑光标所在的图（双击图也可编辑）',
        onclick: function () {
            var img = currentImg();
            openDialog(img);
            editor.focus();
        },
        onPostRender: function () {
            applyIcon(this);
        }
    });

    // 双击已渲染的图 -> 打开源码编辑
    editor.on('dblclick', function (e) {
        var t = e.target;
        if (t && t.nodeName === 'IMG' && editor.dom.hasClass(t, 'syno-mermaid')) {
            e.preventDefault();
            openDialog(t);
        }
    });

    // 只在正文确实含图表时才预热：3.4MB 的库不该为每篇纯文字笔记解析一遍
    editor.on('init', function () {
        window.setTimeout(function () {
            var body = editor.getBody && editor.getBody();
            if (!body) { return; }
            if (!body.querySelector('img.syno-mermaid, pre[data-md-lang="mermaid"]')) { return; }
            ensureLib(function () { /* 预热：失败也无所谓，用到时还会重试 */ });
        }, 900);
    });

    // 自动修复老版本插入的裂图（src 里的 SVG 非法，浏览器加载失败）
    var repairTimer = null;
    function scheduleRepair() {
        if (repairTimer) { window.clearTimeout(repairTimer); }
        repairTimer = window.setTimeout(function () { repairTimer = null; repairImages(); }, 600);
    }
    editor.on('init', scheduleRepair);
    editor.on('SetContent', scheduleRepair);

    return {
        // 暴露给外部（调试 / 测试 / 未来的批量入口）
        render: render,
        renderBlocks: renderBlocks,
        buildImg: buildImg,
        zoom: openZoom,
        repairImages: repairImages
    };
});
